  "Os produtos sincronizados entram no catálogo que o assistente consulta. Os pedidos associados ao contato aparecem no histórico de compras.": "Synced products are added to the catalog the assistant consults. Orders associated with the contact appear in the purchase history.",
  "Shopify: os últimos 60 dias de pedidos dependem das permissões do aplicativo. Informações de clientes podem exigir autorização adicional da Shopify. Nenhuma compra ou alteração na loja é feita por estas conexões.": "Shopify: the last 60 days of orders depend on app permissions. Customer information may require additional authorization from Shopify. No purchases or changes to the store are made through these connections.",
  "Histórico de sincronização": "Sync history",
  "Acompanhe o que foi importado e resolva falhas antes de afetarem o atendimento.": "Track what has been imported and resolve errors before they affect support.",
  "Verifique as permissões e use Sincronizar para tentar novamente.": "Check permissions and use Sync to try again.",
  "Sua loja continua funcionando normalmente. Vamos ler o catálogo e os pedidos para ajudar no atendimento.": "Your store will continue to function normally. We will read the catalog and orders to assist with support.",
  "Endereço da loja": "Store URL",
  "Você será levado à Shopify para autorizar o acesso. Depois voltará para acompanhar a sincronização.": "You will be taken to Shopify to authorize access. You will then return to track the synchronization.",
  "Na sua loja: WooCommerce → Configurações → Avançado → REST API. Crie uma chave com permissão de leitura e informe o par abaixo.": "In your store: WooCommerce → Settings → Advanced → REST API. Create a key with read permissions and enter the pair below.",
  "Use a credencial de um aplicativo próprio com leitura de produtos, estoque e pedidos. Para conexão com renovação automática, solicite a ativação da autorização Shopify ao administrador.": "Use the credentials of a custom app with read access to products, inventory, and orders. For a connection with automatic renewal, request that the administrator activate Shopify authorization.",
