  "Responder em várias mensagens curtas (como uma pessoa digita)": "Reply in multiple short messages (like a person typing)",
  "Em vez de um bloco único, a resposta sai em bolhas separadas, espaçadas pelo mesmo ritmo anti-banimento do envio. O agente também é instruído a escrever em parágrafos curtos.": "Instead of a single block, the response is sent in separate bubbles, spaced by the same anti-ban rhythm used for sending. The agent is also instructed to write in short paragraphs.",
  "Tamanho máximo por bolha (80–4000)": "Maximum size per bubble (80–4000)",
  "O que o agente pode fazer": "What the agent can do",
  "Ligue por jornada de trabalho. O agente só consegue fazer o que estiver ligado aqui — e o que estiver ligado, ele fará sozinho durante o atendimento.": "Enable by workday. The agent can only perform what is enabled here—and whatever is enabled, it will do automatically during the support session.",
  "Quando ele entra em ação": "When it takes action",
  "Passar para uma pessoa": "Hand over to a person",
  "Deixar o agente chamar uma pessoa quando perceber que não é caso dele": "Let the agent call a person when it realizes the issue is not for it to handle",
  "Pedir ajuda sem sair da conversa": "Ask for help without leaving the conversation",
  "Deixar o agente pedir uma tarefa a alguém e seguir conversando": "Let the agent request a task from someone and continue the conversation",
  "Diferente de passar a conversa: aqui o agente continua atendendo. Quando esbarra em algo que só uma pessoa resolve — aprovar um desconto, por exemplo — ele abre um pedido interno e retoma assim que for respondido.": "Unlike transferring the conversation: here the agent continues providing support. When it encounters something only a person can resolve—approving a discount, for example—it opens an internal request and resumes as soon as it is answered.",
  "Follow-up": "Follow-up",
  "Retomar sozinho quem parou de responder, para o interessado não sumir sem ninguém perceber.": "Automatically follow up with those who stopped responding, so leads don't disappear unnoticed.",
