  "Em que negócios ele pode mexer": "Which pipelines it can manage",
  "Marque os funis que este assistente cuida. Ele conversa com qualquer cliente, mas só move, edita ou encerra negócio dos funis marcados aqui.": "Select the pipelines this assistant manages. It can talk to any customer, but it will only move, edit, or close deals in the pipelines selected here.",
  "Você ainda não tem nenhum funil. Crie um em Funis para poder liberar o assistente.": "You don't have any pipelines yet. Create one in Pipelines to enable the assistant.",
  "(é para cá que vão as conversas novas)": "(this is where new conversations go)",
  "— ele não sabe organizar este funil ainda": "— it doesn't know how to organize this pipeline yet",
  "Sem nenhum funil marcado, ele conversa com os clientes normalmente, mas não mexe em negócio nenhum — nem move, nem encerra, nem marca.": "With no pipeline selected, it chats with customers normally but doesn't touch any deals — it won't move, close, or mark them.",
  "Você marcou": "You selected",
  ", mas ninguém disse ao assistente o que cada etapa desse funil significa — ele vai atender e deixar os negócios parados onde estão.": ", but no one told the assistant what each stage of this pipeline means — it will provide support and leave the deals stuck where they are.",
  "funis em que ninguém disse ao assistente o que cada etapa significa — ele vai atender e deixar os negócios parados onde estão.": "pipelines where no one told the assistant what each stage means — it will provide support and leave the deals stuck where they are.",
  " Isso se configura em Configurações › Funis.": " This is configured in Settings › Pipelines.",
  "As conversas novas viram negócio em": "New conversations become deals in",
  ", que não está marcado. O assistente vai atender e os negócios vão se acumular ali sem que ele possa organizá-los.": ", which is not selected. The assistant will provide support and the deals will pile up there without it being able to organize them.",
