  "Não responder às mensagens que saem do seu próprio número": "Do not respond to messages sent from your own number",
  "Só responder quando a mensagem falar de algo específico (opcional)": "Only respond when the message mentions something specific (optional)",
  "Ex.: pedido|status|orçamento": "Ex.: order|status|quote",
  "Deixe em branco para o agente responder a tudo. Se preencher, ele só entra quando a mensagem contiver uma dessas palavras — separe por barra vertical (|). Aceita expressão regular, para quem já conhece.": "Leave blank for the agent to respond to everything. If filled, it only intervenes when the message contains one of these words — separate them with a vertical bar (|). Regular expressions are supported for those who know how to use them.",
