  "Custa": "Costs",
  ". O modelo usado se escolhe em": ". The model used is selected in",
  "Provedores de IA": "AI providers",
  "Modelo padrão": "Default model",
  "Vale em todo ponto que você não configurou individualmente — hoje,": "Applies to every point you haven't configured individually — today,",
  "Trocar aqui muda todos eles de uma vez.": "Changing it here updates them all at once.",
  "Salvar padrão": "Save default",
  "O padrão agora é": "The default is now",
  "pontos precisam de um modelo especialista (embedding ou áudio) e não seguem este padrão — configure cada um abaixo:": "points require a specialist model (embedding or audio) and do not follow this default — configure each one below:",
  "Antes de cada mensagem sair": "Before each message is sent",
  "O assistente escreve, e o sistema confere. São": "The assistant writes, and the system checks. There are",
  "verificações, nesta ordem — a primeira que barra interrompe as seguintes, e o assistente recebe de volta o motivo para reescrever.": "checks, in this order — the first one to block stops the subsequent ones, and the assistant receives the reason to rewrite.",
  "Antes de o assistente ler": "Before the assistant reads",
  "Esta roda sobre a mensagem que chega, antes das outras — por isso aparece separada.": "This runs on the incoming message before the others — which is why it appears separately.",
  "Nenhuma conversa passou por aqui nos últimos": "No conversations have passed through here in the last",
  "dias. Assim que o assistente atender alguém, o que ele organizar aparece nesta área.": "days. As soon as the assistant helps someone, what it organizes will appear in this area.",
  "Como está indo (últimos": "How it's going (last",
  "dias)": "days)",
  "Organizou o sistema em": "The system organized",
  "conversas.": "conversations.",
  "De": "Of",
  "promessas feitas ao cliente,": "promises made to the customer,",
  "ficaram com um responsável": "were assigned to someone",
  " — e ": " — and ",
  " não.": " were not.",
  "Elas aparecem na Central de avisos, uma por conversa.": "They appear in the Notification Center, one per conversation.",
  "Em": "In",
  "delas o assistente tinha algo a registrar e nenhuma capacidade marcada para isso — o que resolve é marcar abaixo o que ele pode fazer.": "of them, the assistant had something to record but no capability marked for it — to resolve this, mark what it can do below.",
  "Deixar o agente organizar o sistema depois de cada conversa": "Let the agent organize the system after each conversation",
  "Quem conversa com o cliente é uma coisa; quem mantém o sistema em dia é outra. Separar os dois evita que o assistente comente com o cliente o que está fazendo por dentro — e é o que faz ele realmente registrar, em vez de só responder bem.": "Who talks to the customer is one thing; who keeps the system up to date is another. Separating the two prevents the assistant from commenting to the customer about what it is doing internally — and it is what actually makes it record, instead of just responding well.",
  "Com isto desligado:": "With this turned off:",
  "o assistente continua atendendo e o básico continua sendo registrado sozinho — a etapa do cliente, o retorno que ele prometeu e o histórico da conversa.": "the assistant keeps responding and the basics keep being recorded automatically — the customer's stage, the follow-up they promised, and the conversation history.",
  "O que ele deixa de fazer é": "What it stops doing is",
  "decidir sobre a operação": "deciding on the operation",
  ": abrir chamados, distribuir para a pessoa certa, organizar marcadores e etapas. Isso passa a ser trabalho de alguém do time.": ": opening tickets, routing to the right person, organizing tags and stages. This becomes a team member's job.",
  "A inteligência que ele usa para organizar": "The intelligence it uses to organize",
  "Pode ser diferente da que conversa. Organizar o sistema é uma tarefa mais mecânica que atender uma pessoa — costuma sair bem com um modelo mais barato.": "Can be different from the one that converses. Organizing the system is a more mechanical task than serving a person — it usually works well with a cheaper model.",
  "A mesma que conversa": "The same one that converses",
  "Usar a mesma que conversa": "Use the same one that converses",
  "O que ele pode mexer no sistema": "What it can change in the system",
  "Esta lista é só deste papel — nada aqui é usado enquanto ele conversa com o cliente. Ligue por jornada de trabalho.": "This list is only for this role — nothing here is used while conversing with the customer. Enable according to the work shift.",
  "Sem nada marcado, ele ainda avisa você quando o assistente prometer algo a um cliente e ninguém cumprir — mas não consegue resolver sozinho.": "With nothing selected, it will still notify you when the assistant promises something to a customer and no one fulfills it — but it won't be able to solve it on its own.",
