  "Top K = quantos trechos buscar. Similarity threshold = mínimo de relevância (cosine). Confidence = limiar abaixo do qual o agent escala para humano.": "Top K = how many snippets to search. Similarity threshold = minimum relevance (cosine). Confidence = threshold below which the agent escalates to a human.",
  "Chaves de acesso à IA": "AI access keys",
  "A conta de inteligência artificial é sua: você contrata direto na Anthropic, OpenAI ou Google e cola a chave aqui. Ela é guardada criptografada e nunca mais aparece na tela depois de salva — nem para você.": "The AI account is yours: you subscribe directly with Anthropic, OpenAI, or Google and paste the key here. It is stored encrypted and never appears on the screen again after being saved — not even for you.",
  "Nenhuma chave cadastrada ainda": "No keys registered yet",
  "Seus agentes só conseguem pensar depois que você cola aqui uma chave da Anthropic, da OpenAI ou do Google. A cobrança vai direto para a sua conta no provedor, e a chave fica guardada criptografada.": "Your agents can only think after you paste an Anthropic, OpenAI, or Google key here. Billing goes directly to your account with the provider, and the key is stored encrypted.",
  "Adicionar credencial": "Add credential",
  "Validada": "Validated",
