  "Inválida": "Invalid",
  "A validação não terminou. Clique em revalidar para testar a chave agora.": "Validation did not finish. Click revalidate to test the key now.",
  "O provedor recusou a chave. Confira se copiou inteira ou gere uma nova.": "The provider rejected the key. Check if you copied it entirely or generate a new one.",
  "O provedor limitou as chamadas desta chave. Tente de novo em alguns minutos.": "The provider limited calls for this key. Try again in a few minutes.",
  "O provedor está fora do ar. A chave pode estar certa; revalide mais tarde.": "The provider is down. The key might be correct; revalidate later.",
  "Não foi possível falar com o provedor a partir deste servidor. Revalide mais tarde.": "Could not reach the provider from this server. Revalidate later.",
  "Falha na validação": "Validation failed",
  "Pegar chave em": "Get key at",
  "O padrão recomendado para conversar com o cliente: é o que melhor segue instruções longas e usa as ferramentas do CRM.": "The recommended standard for talking to customers: it best follows long instructions and uses CRM tools.",
  "Necessário para transcrever áudio e para indexar o seu material — esses dois pontos usam tecnologia da OpenAI mesmo quando o resto está em outro provedor.": "Required to transcribe audio and index your material — these two points use OpenAI technology even when the rest is on another provider.",
  "Alternativa com contexto muito longo e custo baixo para tarefas de classificação.": "Alternative with very long context and low cost for classification tasks.",
  "Uma chave só dá acesso a centenas de modelos de dezenas de fabricantes, inclusive os gratuitos. É o caminho mais simples para experimentar sem abrir conta em cada provedor.": "A single key gives access to hundreds of models from dozens of providers, including free ones. It is the simplest way to experiment without opening an account with each provider.",
