  "Identificação": "Identification",
  "O número não pode ser trocado depois de criado — crie outro roteador para um número diferente.": "The number cannot be changed once created — create another router for a different number.",
  "Ativo — está roteando as conversas deste número": "Active — currently routing conversations for this number",
  "Inativo — não roteia nada": "Inactive — does not route anything",
