  "Modelo do classificador": "Classifier model",
  "Automático — usa o provedor da organização": "Automatic — uses the organization's provider",
  "chave desta instalação": "key for this installation",
  "Nenhuma chave de IA utilizável nesta organização — cadastre uma em Agentes IA › Credenciais para poder escolher o modelo.": "No usable AI key in this organization — add one in AI Agents › Credentials to be able to choose a model.",
  "Só aparecem modelos de provedores com chave cadastrada aqui. Se a conta do provedor estiver sem crédito, a identificação falha e tudo cai no fallback.": "Only models from providers with a registered key will appear here. If the provider's account runs out of credits, identification fails and everything falls back.",
  "Se nenhuma intenção casar": "If no intent matches",
  "Agente de fallback": "Fallback agent",
  "Nenhum — responde com o atendimento padrão": "None — responds with default support",
  "Quando a IA não tem certeza do que o cliente quer, ela chama este agente em vez de travar a conversa.": "When the AI is unsure of what the customer wants, it calls this agent instead of stalling the conversation.",
  "Intenções": "Intents",
  "Cada intenção descreve uma situação e diz qual agente deve assumir a conversa quando o cliente quer aquilo.": "Each intent describes a situation and specifies which agent should take over the conversation when the customer wants that.",
  "Intenção": "Intent",
  "Nenhuma intenção ainda. Sem intenções, toda conversa cai direto no agente de fallback (ou fica sem resposta automática, se você não escolher um).": "No intents yet. Without intents, all conversations go directly to the fallback agent (or are left without an automatic response if you don't choose one).",
  "O número volta a ser atendido pelos gatilhos normais dos agentes (sem roteamento por intenção). As intenções deste roteador são apagadas junto. Não é possível desfazer.": "The number will be handled again by normal agent triggers (without intent routing). The intents for this router will be deleted as well. This action cannot be undone.",
