  "A IA nunca para por gasto. Você vê o número nesta tela e decide o que fazer.": "AI never stops due to spending. You can see the number on this screen and decide what to do.",
  "A IA para de responder ao chegar em": "AI stops responding when it reaches",
  "A parada começa a valer": "The pause takes effect",
  "A parada começa a valer em": "The pause takes effect on",
  "A proteção de gasto está desligada nesta instalação (AI_BUDGET_ENFORCEMENT=off). O que estiver escolhido aqui não vale enquanto quem cuida do servidor não religar.": "Spend protection is turned off in this installation (AI_BUDGET_ENFORCEMENT=off). What is selected here will not take effect until the server administrator turns it back on.",
  "Abrimos um aviso na Central de avisos. A IA continua respondendo normalmente.": "We've created an alert in the Notification Center. The AI continues responding normally.",
  "Aguardando decisão": "Awaiting decision",
  "Aprendizado adicionado.": "Learning added.",
  "Aprendizado arquivado.": "Learning archived.",
  "Aprendizado reativado.": "Learning reactivated.",
  "Aprendizados": "Learnings",
  "Aprovada": "Approved",
  "Aprovar": "Approve",
  "Aprovar e ignorar viram registro — os dois. Quando você decidir a primeira, ela fica aqui.": "Both approving and ignoring are recorded. Once you make your first decision, it will appear here.",
  "As conversas em andamento vão para a fila de atendimento humano — ninguém fica sem resposta, mas alguém precisa responder. Cada uma volta ao automático pelo botão \"Devolver ao automático\" no cabeçalho dela.": "Ongoing conversations go to the human support queue — no one is left unanswered, but someone needs to reply. Each one can return to automatic mode via the \"Return to automatic\" button in its header.",
  "Assuntos mais procurados": "Top searched topics",
  "Atendimentos com IA": "AI support sessions",
  "Até": "Up to",
  "Até lá, só avisamos.": "Until then, we only notify you.",
  "Avisamos ao passar de": "We notify when exceeding",
  "Avisar ao chegar em (% do limite)": "Alert when reaching (% of limit)",
  "Avisos que você marcar como resolvidos ficam aqui.": "Alerts you mark as resolved appear here.",
  "Cada linha aqui é uma coisa que está limitando seu agente, e o que fazer a respeito — às vezes você mesmo, às vezes quem cuida da sua instalação.": "Each line here is something limiting your agent, and what to do about it — sometimes yourself, sometimes whoever manages your installation.",
  "Cada linha é uma coisa nova que o agente passou a saber, na ordem em que aconteceu.": "Each line is something new the agent learned, in the order it happened.",
