  "Custo no período": "Cost in period",
  "Deixe em branco para usar o endereço oficial do provedor. Use isto para apontar para um gateway compatível com a API da OpenAI — inclusive um modelo rodando na sua própria máquina.": "Leave blank to use the provider's official address. Use this to point to an OpenAI API-compatible gateway — including a model running on your own machine.",
  "Descreva a regra ou o aprendizado em texto simples.": "Describe the rule or learning in plain text.",
  "Desinstalar": "Uninstall",
  "Disponível depois de salvar \"Me avisar\" — e, quando você armar a parada, ela só começa a valer 72 horas depois.": "Available after saving \"Notify me\" — and once you set up the stop, it only takes effect after 72 hours.",
