  "Este ponto usa o modelo definido na versão publicada do agente.": "This point uses the model defined in the agent's published version.",
  "Ex.: Nunca prometa desconto sem confirmar com um humano. Horário de atendimento: 9h–18h, seg-sex. Sempre chame o cliente pelo primeiro nome.": "E.g., Never promise a discount without confirming with a human. Business hours: 9 AM–6 PM, Mon–Fri. Always address the customer by their first name.",
