  "carregado no editor. Clique em \"Publicar versão\" para confirmar.": "loaded into the editor. Click \"Publish version\" to confirm.",
  "código": "code",
  "da instalação": "from installation",
  "depois de salvar. É o tempo de você ver o aviso chegar antes que alguma conversa pare.": "after saving. This gives you time to see the alert arrive before any conversation stops.",
  "desinstalada.": "uninstalled.",
