  "Nada foi ajustado — a escala acima mostra onde a sua cor entra.": "Nothing was adjusted — the scale above shows where your color fits in.",
  "Do jeito que está, esta cor não chegaria à tela: o sistema continuaria com as cores padrão dele.": "As it stands, this color would not reach the screen: the system would continue using its default colors.",
