  "O valor gravado para a cor não está na forma que o sistema entende.": "The saved color value is not in a format the system understands.",
  "A cor gravada não é um código de cor válido.": "The saved color is not a valid color code.",
  "A cor foi gravada por uma versão mais nova do sistema, e esta não sabe lê-la.": "The color was saved by a newer version of the system, and this version cannot read it.",
  "A cor foi salva por outra versão do sistema. Ela continua valendo — esta versão recalcula os tons a partir dela.": "The color was saved by another version of the system. It remains valid — this version recalculates the shades based on it.",
  "Esta versão do sistema não sabe onde aplicar a cor gravada, então ela não pinta a interface.": "This system version does not know where to apply the saved color, so it will not paint the interface.",
  "A cor está guardada só como identidade: ela aparece no logo, mas não pinta os botões.": "The color is saved only as an identity: it appears in the logo, but does not paint the buttons.",
  "O cálculo dos tons a partir dessa cor não terminou.": "The calculation of shades from this color did not finish.",
  "Sua cor é um tom neutro (cinza, preto ou branco), e uma cor assim não destaca nada na tela. Os botões seguem com a cor padrão do sistema, e a sua fica reservada ao logo.": "Your color is a neutral tone (gray, black, or white), and such a color does not highlight anything on the screen. The buttons remain with the system default color, and yours is reserved for the logo.",
  "Não existe tom desta cor que deixe todos os elementos legíveis. Alguns detalhes — como o contorno que marca o campo em foco — ficam difíceis de enxergar.": "There is no shade of this color that makes all elements legible. Some details — such as the outline marking the field in focus — become difficult to see.",
  "A verificação de segurança barrou o resultado antes de ele chegar à tela, e a marca não foi aplicada.": "The security check blocked the result before it reached the screen, and the branding was not applied.",
  "O sistema recusou a cor gravada por um motivo que esta versão não sabe explicar.": "The system rejected the saved color for a reason this version cannot explain.",
