  "Ex.: Agradeça o interesse citando o segmento que a pessoa informou, mostre em uma frase como a gente resolve a dificuldade que ela descreveu, e pergunte qual o melhor horário para conversar.": "Ex.: Thank them for their interest by mentioning the segment they provided, show in one sentence how we solve the difficulty they described, and ask for the best time to talk.",
