  "Proteção de envio atualizada.": "Sending protection updated.",
  "Proteção de envio —": "Sending protection —",
  "Estes limites protegem o número contra bloqueio do WhatsApp. Campo vazio usa o padrão seguro do sistema (mostrado no campo).": "These limits protect the number from being blocked by WhatsApp. Leaving the field empty uses the system's safe default (shown in the field).",
  "A ordem de preferência vai de 0 a 1000.": "The preference order ranges from 0 to 1000.",
  "Este número é usado desde": "This number has been in use since",
  "A conexão pode ser nova sem que o número seja. O aquecimento conta a idade do NÚMERO — em branco, ele é tratado como recém-criado e começa liberando pouco por dia. Uma data já salva não some se você limpar o campo: para mudá-la, informe outra.": "The connection may be new, but the number might not be. The warm-up counts the age of the NUMBER — if left blank, it is treated as newly created and starts with a low daily limit. A saved date will not disappear if you clear the field: to change it, enter a new one.",
  "Este número já está aquecido — pular o aquecimento": "This number is already warmed up — skip warm-up",
  "Vale só o teto diário abaixo. Use apenas se o número já envia há semanas: pular o aquecimento num número novo é o caminho mais rápido para o bloqueio.": "Only the daily cap below applies. Use this only if the number has been sending messages for weeks: skipping warm-up on a new number is the fastest way to get blocked.",
  "Número com": "Number with",
  "dia(s) de uso — já formado. Vale só o teto diário abaixo.": "day(s) of use — already established. Only the daily cap below applies.",
  "Hoje o aquecimento libera": "Today, the warm-up allows",
  "envio(s) — o número tem": "send(s) — the number has",
  "dia(s) de uso. Enquanto esse número for menor que o teto diário, é ELE que limita, e mexer no teto diário não muda nada.": "day(s) of use. As long as this number is lower than the daily cap, IT is the limiting factor, and changing the daily cap will have no effect.",
  "Janela de envio (horário local)": "Sending window (local time)",
  "Hora de início da janela": "Window start time",
  "h até": "h until",
  "Hora de fim da janela": "Window end time",
  "O assistente só envia mensagens dentro desta janela. Fora dela, a resposta fica agendada para a próxima abertura — você vê o motivo na conversa.": "The assistant only sends messages within this window. Outside of it, the response is scheduled for the next opening — you can see the reason in the conversation.",
  "Enviar aos domingos": "Send on Sundays",
  "Ligado por padrão: quem escreve no domingo espera resposta no domingo. Desligue se você faz prospecção ativa e prefere não incomodar no fim de semana.": "Enabled by default: those who write on Sunday expect a response on Sunday. Disable this if you do active prospecting and prefer not to disturb on the weekend.",
