  "Intervalo mínimo entre mensagens do mesmo número, mais uma variação aleatória — ritmo cravado parece robô para o WhatsApp.": "Minimum interval between messages from the same number, plus a random variation — a fixed pace looks like a bot to WhatsApp.",
