  "Qualidade do número segundo a plataforma:": "Number quality according to the platform:",
  "O endereço que o provedor usa para entregar as mensagens. O segredo não é mostrado de novo — para obter um novo, reconecte.": "The address the provider uses to deliver messages. The secret is not shown again — to get a new one, reconnect.",
