  "O serviço do WhatsApp não está configurado.": "The WhatsApp service is not configured.",
  "Faltam o endereço e a chave do serviço (": "The service address and key are missing (",
  ") nas variáveis de ambiente desta instalação. Enquanto isso, não dá para conectar, reconectar nem excluir os números pareados por QR — excluir um número também o desconecta do aparelho, e sem o serviço isso não acontece.": ") in this installation's environment variables. In the meantime, you cannot connect, reconnect, or delete QR-paired numbers — deleting a number also disconnects it from the device, and without the service, this does not happen.",
  "Se você roda tudo na mesma máquina, o container sobe com": "If you are running everything on the same machine, the container starts with",
  ". Já apareceu aqui o caso oposto: o container no ar e o endereço configurado apontando para um lugar que não existe — subir o container de novo não conserta isso.": ". We have encountered the opposite case: the container is up and the configured address points to a non-existent location — restarting the container does not fix this.",
  "Esta instalação está com o banco atrasado.": "This installation's database is outdated.",
