  "Perdido": "Lost",
  "O relatório de LGPD entregue ao cliente traz a RAZÃO SOCIAL da sua empresa, e não o nome aqui de cima — é ela que responde legalmente pelos dados. Confira o campo \"Razão social\" em Configurações → Organização.": "The LGPD report delivered to the client displays your company's LEGAL NAME, not the name above — it is the entity legally responsible for the data. Check the \"Legal name\" field in Settings → Organization.",
