  "isso protege o número contra bloqueio do WhatsApp.": "this protects the number from being blocked by WhatsApp.",
  "Este número ainda está em aquecimento e o limite diário de envios dele foi atingido. Enviar além disso arriscaria bloqueio pelo WhatsApp — libera de novo amanhã, a partir das": "This number is still warming up and its daily sending limit has been reached. Sending more would risk a WhatsApp block — it will be available again tomorrow, starting at",
  "O limite diário de envios do número foi atingido — proteção contra bloqueio do WhatsApp. Libera de novo amanhã, a partir das": "The daily sending limit for this number has been reached — protection against WhatsApp blocking. It will be available again tomorrow, starting at",
  "A mesma mensagem estava se repetindo em massa por este número. O envio foi segurado para variar o texto e não parecer robô para o WhatsApp.": "The same message was being sent in bulk from this number. The sending was held to vary the text and avoid appearing like a bot to WhatsApp.",
  "O contato pediu para não receber mensagens (opt-out). Nada será enviado a ele.": "The contact has opted out of receiving messages. Nothing will be sent to them.",
  "Este contato foi anonimizado (LGPD) — é proibido enviar qualquer mensagem a ele.": "This contact has been anonymized (LGPD) — it is prohibited to send any messages to them.",
  "Não há base legal (LGPD) para o primeiro contato de prospecção com este lead. O time precisa regularizar o cadastro antes de abordar.": "There is no legal basis (LGPD) for the first prospecting contact with this lead. The team must regularize the registration before reaching out.",
  "A resposta prometia um preço ou condição fora da tabela aprovada. O assistente foi orientado a corrigir antes de enviar.": "The response promised a price or condition outside the approved table. The assistant was instructed to correct it before sending.",
  "A resposta continha uma promessa não autorizada. O assistente foi orientado a reescrever antes de enviar.": "The response contained an unauthorized promise. The assistant was instructed to rewrite it before sending.",
  "A primeira mensagem a um contato novo precisa se apresentar como assistente virtual. O assistente foi orientado a corrigir antes de enviar.": "The first message to a new contact must introduce the virtual assistant. The assistant was instructed to correct it before sending.",
  "Uma trava de segurança segurou esta resposta": "A security guardrail held this response",
  "Ela não foi enviada ao contato.": "It was not sent to the contact.",
  "Resposta segurada pela proteção do número": "Response held by number protection",
