  "Sua conta foi confirmada, mas a organização inicial ainda não foi criada. Informe o nome da sua empresa para concluir o primeiro acesso e abrir o onboarding do CRM.": "Your account has been confirmed, but the initial organization has not been created yet. Enter your company name to complete your first login and start the CRM onboarding.",
  "Se você recebeu um convite, não crie uma organização nova. Use o link do convite ou peça ao administrador para reenviá-lo.": "If you received an invitation, do not create a new organization. Use the invitation link or ask the administrator to resend it.",
