  "Pular tudo (DEV)": "Skip all (DEV)",
  "Como se chama o seu negócio?": "What is the name of your business?",
  "É o nome que aparece para o seu time e nos relatórios. Pode ser clínica, loja, escritório — o que for seu.": "This is the name that appears to your team and in reports. It could be a clinic, store, office — whatever is yours.",
  "O que vocês fazem?": "What do you do?",
  "Ex.: clínica odontológica, ou venda de roupa fitness pelo WhatsApp": "E.g., dental clinic, or selling fitness apparel via WhatsApp",
  "Uma linha basta. É com isso que seu funcionário aprende com quem ele está falando — e que a gente monta o quadro de clientes do seu jeito.": "One line is enough. This helps your employee learn who they are talking to — and helps us set up your customer dashboard your way.",
  "Onde você atende": "Where you provide support",
