  "Dê um telefone a ele": "Assign a phone number",
  "É por este número que ele vai atender seus clientes. Se você conecta pelo celular, tenha ele por perto.": "This is the number they will use to support your customers. If you are connecting via mobile, keep it nearby.",
  "Pronto para conectar": "Ready to connect",
  "O código expirou": "The code has expired",
  "Não consegui falar com o WhatsApp": "Could not connect to WhatsApp",
  "Escaneie o código abaixo com o celular que vai atender.": "Scan the code below with the phone that will be used for support.",
  "Isso leva alguns segundos. O código aparece aqui sozinho.": "This takes a few seconds. The code will appear here automatically.",
  "O número está no ar. Seguindo para o próximo passo.": "The number is live. Moving to the next step.",
