  "o servidor respondeu": "the server responded",
  "Não consegui gerar outro código. Tente de novo em alguns segundos.": "Could not generate another code. Try again in a few seconds.",
  "Não consegui falar com o servidor. Confira sua conexão e tente de novo.": "Could not connect to the server. Check your connection and try again.",
  "Como você já usa esse número?": "How do you already use this number?",
  "Existe mais de um jeito de ter WhatsApp para empresa, e cada um conecta de um jeito. Se você nunca ouviu falar dos outros dois, é o primeiro.": "There is more than one way to have WhatsApp for business, and each connects differently. If you haven't heard of the other two, this is the first one.",
  "Leio um código com o celular": "Scan a code with my phone",
  "É assim para quase todo mundo. Você abre o WhatsApp no celular que vai atender e aponta para um código que aparece aqui.": "This is how it works for almost everyone. You open WhatsApp on the phone that will handle support and point it at a code that appears here.",
  "Tenho conta oficial na Meta": "I have an official Meta account",
  "Você cadastrou o número na Meta e tem as credenciais em mãos. Não usa o celular para conectar.": "You registered the number with Meta and have the credentials in hand. You don't use a phone to connect.",
  "Contrato de um provedor parceiro": "Contracted a partner provider",
  "Uma empresa parceira cuida do seu WhatsApp e te deu uma chave de acesso.": "A partner company manages your WhatsApp and provided you with an access key.",
  "Este servidor ainda não está pronto para RECEBER por este caminho.": "This server is not yet ready to RECEIVE via this path.",
  "Dá para conectar e já enviar, mas as respostas do cliente não vão chegar até quem instalou o sistema completar uma configuração no servidor. Se você quer atender hoje, o caminho do código com o celular funciona agora — e dá para trocar depois, sem perder nada.": "You can connect and send messages now, but customer replies won't arrive until the person who installed the system completes a server configuration. If you want to start supporting customers today, the phone code method works immediately — and you can switch later without losing anything.",
  "O WhatsApp desta instalação ainda não subiu.": "The WhatsApp for this installation is not up yet.",
  "Ele roda no seu próprio servidor. Dá para seguir sem ele agora e conectar o número depois, em": "It runs on your own server. You can continue without it for now and connect the number later in",
  "Canais › Conexões": "Channels › Connections",
  "seu funcionário fica pronto de qualquer jeito, só não terá por onde atender ainda.": "your employee will be ready regardless, they just won't have a way to handle support yet.",
  "Não consegui carregar o código agora. Ele deve reaparecer sozinho em instantes — se não aparecer, gere outro abaixo.": "Could not load the code right now. It should reappear on its own in a moment — if it doesn't appear, generate another one below.",
  "Código QR para conectar o WhatsApp": "QR Code to connect WhatsApp",
  "Conectado! Avançando…": "Connected! Moving on…",
  "O código expirou antes de alguém escanear. É normal — ele vale só alguns minutos.": "The code expired before it was scanned. That's normal — it's only valid for a few minutes.",
  "Deixe o WhatsApp já aberto em": "Keep WhatsApp already open in",
  "Aparelhos conectados": "Linked devices",
  "antes de gerar o próximo, que aí dá tempo de sobra.": "before generating the next one, so you have plenty of time.",
  "Gerar novo QR Code": "Generate new QR Code",
  "O serviço de WhatsApp desta instalação não respondeu. Ele roda no seu servidor, junto com o resto do sistema — quem instalou consegue religá-lo.": "The WhatsApp service for this installation did not respond. It runs on your server, along with the rest of the system — the person who installed it can restart it.",
