  "Como ele vai se chamar": "What will they be called",
  "É o nome que aparece para o seu time. O cliente vê só a conversa.": "This is the name that appears to your team. The customer only sees the conversation.",
  "O jeito dele falar": "How they speak",
  "As regras da casa (opcional)": "House rules (optional)",
  "Nunca prometa desconto sem confirmar com uma pessoa.": "Never promise a discount without confirming with a person.",
  "Horário de atendimento: 9h às 18h, de segunda a sexta.": "Support hours: 9 am to 6 pm, Monday to Friday.",
  "Sempre chame o cliente pelo primeiro nome.": "Always address the customer by their first name.",
  "O que vale para qualquer atendimento aqui. Pode deixar em branco agora e escrever depois — ele aprende com você ao longo do tempo.": "These apply to all support here. You can leave it blank for now and write it later — they learn from you over time.",
  "Ele já vem sabendo": "They already know",
  "E nunca vai fazer": "And will never do",
  "Essas conferências acontecem antes de cada mensagem sair, e não têm interruptor.": "These checks happen before every message is sent, and they cannot be toggled off.",
