  "rascunho": "draft",
  "— ele ainda não tem com o que pensar.": "— it doesn't have anything to think with yet.",
  "Não achei chave de": "I couldn't find an API key for",
  "nem cadastrada aqui, nem vinda da instalação. Cole a chave no campo acima («o cérebro dele») e crie o atendente de novo — ou cadastre em": "neither registered here nor provided by the installation. Paste the key in the field above (\"its brain\") and create the agent again — or register it in",
  "IA › Credenciais": "AI › Credentials",
  "Continuar sem publicar": "Continue without publishing",
  "— e rascunho não responde mensagem.": "— and a draft does not respond to messages.",
  "Os modelos": "The models",
  "que esta instalação conhece não sabem usar ferramentas — sem isso ele conversaria bem e nunca criaria um cliente nem moveria um negócio no funil. Escolha outra empresa de IA em": "that this installation knows do not support tools — without this, it would chat well but never create a lead or move a deal in the pipeline. Choose another AI provider in",
