  "Importar contatos de planilha": "Import contacts from spreadsheet",
  "Envie um arquivo .csv com cabeçalho — colunas reconhecidas: nome, telefone, email, cpf, nascimento, tags. Excel: use “Salvar como” → “CSV UTF-8”. Máximo de 500 linhas por arquivo.": "Upload a .csv file with a header — recognized columns: nome, telefone, email, cpf, nascimento, tags. Excel: use “Save As” → “CSV UTF-8”. Maximum 500 lines per file.",
  "Este arquivo não parece ser um CSV de texto. No Excel use “Salvar como” → “CSV UTF-8 (delimitado por vírgulas)”.": "This file does not appear to be a text CSV. In Excel, use “Save As” → “CSV UTF-8 (comma delimited)”.",
