  "Não foi possível guardar o segredo com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave.": "The secret could not be stored securely: this installation's encryption key is not active. The server administrator can fix it by running update.sh, which generates and activates the key.",
  "Não foi possível guardar o segredo com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave. Enquanto isso, você pode criar a fonte sem segredo.": "The secret could not be stored securely: this installation's encryption key is not active. The server administrator can fix it by running update.sh, which generates and activates the key. Meanwhile, you can create the source without a secret.",
  "Não foi possível guardar o segredo do webhook com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave.": "The webhook secret could not be stored securely: this installation's encryption key is not active. The server administrator can fix it by running update.sh, which generates and activates the key.",
  "Não foi possível guardar o segredo do webhook com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave. Enquanto isso, você pode criar a ação sem segredo.": "The webhook secret could not be stored securely: this installation's encryption key is not active. The server administrator can fix it by running update.sh, which generates and activates the key. Meanwhile, you can create the action without a secret.",
