  "Nunca mais perca um cliente por demora na resposta": "Never lose a customer to a slow reply again",
  "Todo o WhatsApp da sua empresa em uma tela só. Um atendente de IA responde na hora, com o que você ensinou, e passa a conversa para uma pessoa do time quando o assunto pede.": "Your company's entire WhatsApp on one screen. An AI agent replies right away with what you taught it, and hands the conversation to a team member when needed.",
  "Começar com": "Start with",
  "dias grátis": "days free",
  "Já tenho conta": "I already have an account",
  "Sem cartão para começar": "No card to start",
  "Você usa o número que já tem": "You keep the number you already have",
  "Cancele quando quiser": "Cancel anytime",
  "A venda raramente se perde no preço. Ela se perde no silêncio.": "Sales are rarely lost on price. They're lost in silence.",
  "A resposta demora": "Replies take too long",
  "Quem pergunta às 22h só é atendido no dia seguinte. Até lá, já comprou de quem respondeu primeiro.": "Whoever asks at 10 PM only gets an answer the next day. By then, they've bought from whoever replied first.",
  "A conversa se perde": "The conversation gets lost",
  "Cada pessoa do time guarda um pedaço da história no próprio celular. Ninguém sabe o que já foi combinado.": "Each team member keeps a piece of the story on their own phone. No one knows what was already agreed.",
  "O retorno nunca acontece": "The follow-up never happens",
  "O cliente disse “depois eu vejo” e ninguém voltou nele. É a venda mais barata da empresa, e ela evapora.": "The customer said “I'll think about it” and no one got back to them. It's the cheapest sale a company has, and it evaporates.",
  "Três passos, e o atendimento para de depender de memória": "Three steps, and service stops depending on memory",
  "Conecte o seu WhatsApp": "Connect your WhatsApp",
  "O mesmo número que a sua empresa já usa, por leitura de QR code. Ninguém troca de número e nenhuma conversa se perde.": "The same number your company already uses, by scanning a QR code. No one changes numbers and no conversation is lost.",
  "Ensine o atendente": "Teach the agent",
  "Escreva o que a empresa faz, preço, prazo e as regras. O agente responde a partir disso — e só disso.": "Write what the company does, prices, timelines and rules. The agent answers from that — and only that.",
  "Acompanhe pelo funil": "Track it in the pipeline",
  "Cada conversa vira um card. Você vê quem está esperando, quem comprou e quem esfriou, sem perguntar a ninguém.": "Each conversation becomes a card. You see who's waiting, who bought and who went cold, without asking anyone.",
  "O atendimento inteiro em um lugar só": "All your customer service in one place",
  "Uma caixa de entrada para o time todo": "One inbox for the whole team",
  "Todas as conversas em uma tela, com quem está atendendo o quê à vista de todos.": "All conversations on one screen, with who's handling what visible to everyone.",
  "Agente de IA com a sua base de conhecimento": "AI agent with your knowledge base",
  "Ele responde pelo que você escreveu, não por achismo, e chama uma pessoa quando não sabe.": "It answers from what you wrote, not guesswork, and calls a person when it doesn't know.",
  "Funil de vendas colado na conversa": "Sales pipeline built into the conversation",
  "Arraste o card, leia o histórico inteiro e pare de perguntar em que pé está cada cliente.": "Drag the card, read the whole history and stop asking where each customer stands.",
  "Retorno automático no tempo certo": "Automatic follow-up at the right time",
  "Quem parou de responder recebe uma mensagem de volta sem que ninguém precise lembrar disso.": "Whoever stopped replying gets a message back without anyone needing to remember.",
  "Relatórios de atendimento": "Service reports",
  "Tempo de resposta, volume por pessoa do time e o que de fato virou venda.": "Response time, volume per team member and what actually became a sale.",
  "LGPD desde o primeiro dia": "Privacy from day one",
  "Dados isolados por empresa, registro de acesso e exclusão a pedido do titular.": "Data isolated per company, access logs and deletion on the data subject's request.",
  "Comece liberado. Escolha o plano depois.": "Start with everything unlocked. Choose your plan later.",
  "dias com tudo funcionando, sem cartão. Você só escolhe um plano quando decidir ficar.": "days with everything working, no card. You only choose a plan when you decide to stay.",
  "Recomendado": "Recommended",
  "Começar agora": "Get started",
  "O que costumam perguntar antes de assinar": "What people usually ask before subscribing",
  "Preciso trocar de número?": "Do I need to change my number?",
  "Não. Você conecta o número que a empresa já usa lendo um QR code, e as conversas seguem de onde pararam.": "No. You connect the number your company already uses by scanning a QR code, and conversations continue where they left off.",
  "A IA responde sozinha o tempo todo?": "Does the AI answer on its own all the time?",
  "Só até onde você deixar. Ela responde o que está na base de conhecimento e entrega a conversa a uma pessoa do time quando o assunto sai dali.": "Only as far as you allow. It answers what's in the knowledge base and hands the conversation to a team member when the topic goes beyond that.",
  "O time todo consegue usar?": "Can the whole team use it?",
  "Sim. Cada pessoa entra com o próprio acesso e você decide o que cada uma pode ver e fazer.": "Yes. Each person logs in with their own access and you decide what each one can see and do.",
  "E se eu quiser cancelar?": "What if I want to cancel?",
  "O cancelamento é um clique na própria tela de cobrança, sem falar com ninguém. O acesso continua até o fim do período já pago.": "Canceling is one click on the billing screen itself, without talking to anyone. Access continues until the end of the period already paid.",
  "Onde ficam os dados dos meus clientes?": "Where is my customers' data stored?",
  "Em base isolada por empresa, com registro de quem acessou o quê. Você pode exportar ou apagar os seus dados quando quiser.": "In a database isolated per company, with a log of who accessed what. You can export or delete your data whenever you want.",
  "A próxima pessoa que te chamar no WhatsApp merece resposta agora": "The next person who messages you on WhatsApp deserves an answer now",
  "Crie a conta, conecte o número e veja o primeiro atendimento acontecer sozinho ainda hoje.": "Create your account, connect your number and watch the first conversation happen on its own today.",
