  "atenção": "attention",
  "O assistente prometeu algo ao cliente e ninguém ficou responsável": "The assistant promised the customer something and no one took responsibility",
  "Nesta conversa o assistente combinou algo com o cliente. Ele ainda não tem nenhuma capacidade marcada para registrar isso no sistema, então nada foi agendado nem anotado. Abra a conversa para ver o que foi combinado — e, na tela do assistente, marque o que ele pode fazer.": "In this conversation the assistant agreed on something with the customer. It doesn't have any capability turned on to record that in the system yet, so nothing was scheduled or noted. Open the conversation to see what was agreed — and, on the assistant screen, choose what it can do.",
  "Nesta conversa o assistente combinou algo com o cliente e não registrou nenhum próximo passo para isso — não há retorno agendado. Abra a conversa, veja o que foi combinado e decida quem faz.": "In this conversation the assistant agreed on something with the customer and didn't record any next step for it — no follow-up is scheduled. Open the conversation, see what was agreed and decide who does it.",
  "Nesta conversa o assistente combinou algo com o cliente, e a parte que organiza o sistema não rodou neste atendimento. Nada foi agendado. Abra a conversa para ver o que foi combinado e decida quem faz.": "In this conversation the assistant agreed on something with the customer, and the part that organizes the system didn't run in this conversation. Nothing was scheduled. Open the conversation to see what was agreed and decide who does it.",
  "O agente já sabe": "The agent already knows",
