  "Não consegui guardar o arquivo.": "Couldn't store the file.",
  "Material cadastrado. Estou preparando — em instantes o agente já sabe.": "Material added. I'm preparing it — in a moment the agent will know it.",
  "Material cadastrado. Ele fica esperando a chave da OpenAI para ser preparado.": "Material added. It's waiting for the OpenAI key to be prepared.",
