  "Trecho": "Excerpt",
  "Uma tela não folheia mil pedaços — o restante está no acervo e o agente alcança todos.": "One screen can't page through a thousand pieces — the rest is in the library and the agent reaches all of it.",
  "Perguntas e respostas": "Questions and answers",
  "As dúvidas que se repetem, com a resposta pronta. É o formato que o agente cita melhor, porque cada resposta chega inteira.": "Recurring questions, with the answer ready. It's the format the agent quotes best, because each answer arrives whole.",
  "Um texto do seu negócio — política de troca, tabela de preços, manual, contrato. Envie o arquivo (PDF, Markdown ou texto) ou cole o conteúdo.": "A text about your business — return policy, price list, manual, contract. Upload the file (PDF, Markdown or text) or paste the content.",
