  "Responder o cliente": "Reply to the customer",
  "Escreve a resposta que o cliente lê no WhatsApp, consultando o material do seu negócio e usando as ferramentas do CRM.": "Writes the reply the customer reads on WhatsApp, consulting your business material and using the CRM tools.",
  "O cliente manda mensagem e ninguém responde. A conversa fica parada na Caixa de entrada sem aviso.": "The customer sends a message and no one replies. The conversation sits in the Inbox with no alert.",
  "Trabalhar o funil": "Work the pipeline",
  "Cria o lead, move de etapa e registra o que ficou combinado, enquanto a conversa acontece.": "Creates the lead, moves it between stages and records what was agreed, while the conversation happens.",
  "O cliente é atendido normalmente, mas nada aparece no funil — nenhum lead criado, nenhuma etapa movida.": "The customer is served normally, but nothing shows up in the pipeline — no lead created, no stage moved.",
  "Abordar quem preencheu o formulário": "Reach out to form submissions",
  "Escreve a primeira mensagem para quem acabou de preencher um formulário, usando os campos que a pessoa respondeu e a orientação que você deu na automação.": "Writes the first message to someone who just filled out a form, using the fields they answered and the guidance you gave in the automation.",
  "O lead entra pelo formulário, a automação roda, e a mensagem de abordagem nunca é escrita — o contato fica no funil sem ninguém falar com ele.": "The lead comes in through the form, the automation runs, and the outreach message is never written — the contact sits in the pipeline with no one talking to them.",
  "Sugerir resposta ao atendente": "Suggest a reply to the agent",
  "Escreve um rascunho de resposta para o atendente humano revisar antes de enviar.": "Writes a draft reply for the human agent to review before sending.",
  "O botão de sugerir resposta não traz nada, e o atendente escreve do zero sem saber por quê.": "The suggest-reply button returns nothing, and the agent writes from scratch without knowing why.",
