  "Sem eles ninguém consegue marcar clicando na grade — nem você, nem o agente.": "Without them no one can book by clicking the grid — not you, not the agent.",
  "Não consegui carregar os horários.": "Couldn't load the time slots.",
  "Os blocos ficam bloqueados até eu conseguir — é mais seguro que oferecer um horário que talvez não exista.": "The blocks stay locked until I can — it's safer than offering a time that may not exist.",
  "Nenhum horário livre neste período.": "No free slots in this period.",
