  "Quantas vezes o agente voltou ao cliente por conta própria. Medido sobre as": "How many times the agent went back to the customer on its own. Measured over the",
  "demandas que passaram por atendimento humano.": "requests that went through human service.",
  "Conversas que morreram no silêncio (após": "Conversations that died in silence (after",
  "conversas em que falamos: a pessoa não respondeu e ninguém encerrou.": "conversations where we spoke: the person didn't reply and no one closed it.",
  "Piso:": "Floor:",
  "Conta só a repergunta quase literal — reformulada com outras palavras escapa desta medida.": "Only counts near-literal repeated questions — rephrased in other words escapes this measure.",
  "Igual à mediana: há poucas esperas medidas no período para os dois se separarem.": "Same as the median: there are few measured waits in the period for the two to diverge.",
  "O p90 é a experiência de quem espera mais — a mediana a esconde.": "The p90 is the experience of those who wait the longest — the median hides it.",
  "abertas agora. Cada uma é alguém esperando sem que nada esteja marcado para acontecer.": "open now. Each one is someone waiting with nothing scheduled to happen.",
